function zonedParts(date, timeZone) {
  const dtf = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
  const map = {};
  for (const p of dtf.formatToParts(date)) {
    if (p.type !== "literal") map[p.type] = p.value;
  }
  return { year: +map.year, month: +map.month, day: +map.day, hour: +map.hour, minute: +map.minute, second: +map.second, rawHour: map.hour };
}

function offsetAt(utcMs, timeZone) {
  const p = zonedParts(new Date(utcMs), timeZone);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  return asUtc - utcMs;
}

function twoPass(y, m, d, h, mi, s, timeZone) {
  const guess = Date.UTC(y, m - 1, d, h, mi, s);
  const o1 = offsetAt(guess, timeZone);
  let utc = guess - o1;
  const o2 = offsetAt(utc, timeZone);
  if (o2 !== o1) utc = guess - o2;
  const back = zonedParts(new Date(utc), timeZone);
  return { iso: new Date(utc).toISOString(), back, match: back.year===y && back.month===m && back.day===d && back.hour===h && back.minute===mi && back.second===s };
}

const samples = [
