console.log("twoPass spring 8:00", twoPass(2026,3,8,8,0,0,"America/New_York"));
console.log("twoPass day before spring 8:00", twoPass(2026,3,7,8,0,0,"America/New_York"));
console.log("twoPass fall 1:00", twoPass(2026,11,1,1,0,0,"America/New_York"));
console.log("twoPass fall 8:00", twoPass(2026,11,1,8,0,0,"America/New_York"));
console.log("twoPass day before fall 8:00", twoPass(2026,10,31,8,0,0,"America/New_York"));
console.log("twoPass kolkata midnight", twoPass(2026,3,15,0,0,0,"Asia/Kolkata"));
console.log("twoPass kathmandu midnight", twoPass(2026,3,15,0,0,0,"Asia/Kathmandu"));
console.log("twoPass lord howe", twoPass(2026,3,15,0,0,0,"Australia/Lord_Howe"));

try { Intl.DateTimeFormat("en-US", { timeZone: "Not/AZone" }); console.log("bad zone did not throw"); }
catch (e) { console.log("bad zone", e.name, e.message); }
try { Intl.DateTimeFormat("en-US", { timeZone: "utc" }); console.log("utc lower ok", zonedParts(new Date(), "utc")); }
catch (e) { console.log("utc lower", e.name); }
try { Intl.DateTimeFormat("en-US", { timeZone: "" }); console.log("empty ok"); }
catch (e) { console.log("empty", e.name); }

// hour 24 scan
for (const z of ["UTC", "America/New_York", "Asia/Tokyo", "Pacific/Chatham"]) {
  const start = Date.parse("2026-01-01T00:00:00Z");
  let weird = 0;
