  return { year:+map.year, month:+map.month, day:+map.day, hour:+map.hour, minute:+map.minute, second:+map.second };
}
function offsetAt(utcMs, timeZone) {
  const p = zonedParts(new Date(utcMs), timeZone);
  return Date.UTC(p.year, p.month-1, p.day, p.hour, p.minute, p.second) - utcMs;
}
function instantsOfLocalTime(y,m,d,h,mi,s,timeZone) {
  const naive = Date.UTC(y,m-1,d,h,mi,s);
  const offsets = new Set();
  for (let hp = -1; hp <= 25; hp++) {
    offsets.add(offsetAt(Date.UTC(y,m-1,d,hp,30,0), timeZone));
  }
  const found = [];
  for (const off of offsets) {
    const utc = naive - off;
    const p = zonedParts(new Date(utc), timeZone);
    if (p.year===y && p.month===m && p.day===d && p.hour===h && p.minute===mi && p.second===s) found.push(utc);
  }
  return [...new Set(found)].sort((a,b)=>a-b).map(ms => new Date(ms).toISOString());
}
function firstInstantOfLocalDate(y,m,d,timeZone) {
  const naive = Date.UTC(y,m-1,d);
  let lo = naive - 36*3600_000;
  let hi = naive + 36*3600_000;
  const onOrAfter = (ms) => {
    const p = zonedParts(new Date(ms), timeZone);
    if (p.year !== y) return p.year > y;
    if (p.month !== m) return p.month > m;
    return p.day >= d;
  };
  while (lo+1 < hi) {
    const mid = Math.floor((lo+hi)/2);
    if (onOrAfter(mid)) hi = mid; else lo = mid;
  }
  return new Date(hi).toISOString();
}
