type CivilTime = {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
};

/** Wall-clock parts of `instant` in `timeZone`. Invalid zones throw RangeError. */
function zonedParts(instant: Date, timeZone: string): CivilTime {
  const formatted = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(instant);

  const map: Record<string, string> = {};
  for (const part of formatted) {
    if (part.type !== "literal") map[part.type] = part.value;
  }

  let hour = Number(map.hour);
  let day = Number(map.day);
  let month = Number(map.month);
  let year = Number(map.year);
  if (hour === 24) {
    hour = 0;
    const rolled = new Date(Date.UTC(year, month - 1, day + 1));
    year = rolled.getUTCFullYear();
    month = rolled.getUTCMonth() + 1;
    day = rolled.getUTCDate();
  }

  return {
    year,
    month,
    day,
    hour,
    minute: Number(map.minute),
    second: Number(map.second),
  };
}

function pad(value: number, width: number): string {
  return String(value).padStart(width, "0");
}

/** True when `timeZone` is an IANA name `Intl` accepts. */
export function isKnownTimeZone(timeZone: string): boolean {
  try {
    Intl.DateTimeFormat("en-US", { timeZone }).format(0);
    return true;
  } catch {
    return false;
  }
}

/** Refuses a zone name `Intl` does not recognise. */
export function assertKnownTimeZone(timeZone: string): void {
  if (!isKnownTimeZone(timeZone)) {
    throw new RangeError(`Unknown time zone: "${timeZone}"`);
  }
}

/**
 * `YYYY-MM-DD` calendar date of `value` on the clock in `timeZone`.
 * An unknown zone throws `RangeError`.
 */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const parts = zonedParts(parseIso(value), timeZone);
  return `${pad(parts.year, 4)}-${pad(parts.month, 2)}-${pad(parts.day, 2)}`;
}

/** Offset of `timeZone` at `utcMs`, in milliseconds (local-as-UTC minus UTC). */
function offsetAt(utcMs: number, timeZone: string): number {
  const parts = zonedParts(new Date(utcMs), timeZone);
  const asUtc = Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour,
    parts.minute,
    parts.second,
  );
  return asUtc - utcMs;
}

/**
 * Every UTC instant at which `timeZone` shows the given civil time.
 * Empty when that wall time is skipped (a spring-forward gap). Both sides
 * of a fall-back fold are returned, earliest first.
 */
function instantsOfLocalTime(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
  timeZone: string,
): number[] {
  const naive = Date.UTC(year, month - 1, day, hour, minute, second);
  const offsets = new Set<number>();
  for (let probe = -1; probe <= 25; probe += 1) {
    offsets.add(offsetAt(Date.UTC(year, month - 1, day, probe, 30, 0), timeZone));
  }

  const found: number[] = [];
  for (const offset of offsets) {
    const utc = naive - offset;
    const parts = zonedParts(new Date(utc), timeZone);
    if (
      parts.year === year &&
