 * before `reference`. The start is that same hour on the previous calendar
 * day, so a DST change makes the window 23 or 25 hours long. When today's
 * hour has not arrived yet, the window is the one that ended yesterday.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHour}`);
  }

  const local = zonedParts(reference, timeZone);
  const todayHits = instantsOfLocalTime(
    local.year,
    local.month,
    local.day,
    digestHour,
    0,
    0,
    timeZone,
  ).filter((ms) => ms <= reference.getTime());

  let endMs: number;
  let endYear: number;
  let endMonth: number;
  let endDay: number;

  if (todayHits.length > 0) {
    endMs = todayHits[todayHits.length - 1] ?? todayHits[0]!;
    endYear = local.year;
    endMonth = local.month;
    endDay = local.day;
