    const previous = shiftCalendarDate(local.year, local.month, local.day, -1);
    const previousHits = instantsOfLocalTime(
      previous.year,
      previous.month,
      previous.day,
      digestHour,
      0,
      0,
      timeZone,
    ).filter((ms) => ms <= reference.getTime());
    const end = previousHits[previousHits.length - 1];
    if (end === undefined) {
      throw new RangeError(
        `digest hour ${digestHour} did not occur in ${timeZone}`,
