/** `YYYY-MM-DD` shifted by whole calendar days, independent of DST. */
function shiftYmd(ymd: string, deltaDays: number): string {
  const [year, month, day] = ymd.split("-").map(Number);
  const shifted = new Date(Date.UTC(year!, month! - 1, day! + deltaDays));
  const m = String(shifted.getUTCMonth() + 1).padStart(2, "0");
  const d = String(shifted.getUTCDate()).padStart(2, "0");
  return `${shifted.getUTCFullYear()}-${m}-${d}`;
}

/**
 * An instant that falls on `ymd` in `timeZone`, so `startOfLocalDay` of it
 * is local midnight on that calendar date.
 */
function instantOnLocalDate(ymd: string, timeZone: string): Date {
  const [year, month, day] = ymd.split("-").map(Number);
  let guess = new Date(Date.UTC(year!, month! - 1, day!, 12, 0, 0));
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const got = localDate(toIsoTimestamp(guess), timeZone);
    if (got === ymd) return guess;
    const [gy, gm, gd] = got.split("-").map(Number);
    const delta = Date.UTC(year!, month! - 1, day!) - Date.UTC(gy!, gm! - 1, gd!);
    guess = new Date(guess.getTime() + delta);
  }
  return guess;
}

