          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )

input.new_string:
/**
 * Live, still-open issues whose workspace calendar day containing `dueAt`
 * has ended as of `now`. `now` is the reference instant; the cut-off is local
 * midnight of the workspace day that contains it.
 */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const zoneRow = getDb()
    .select({ timeZone: organizations.timeZone })
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  const cutoff = startOfLocalDay(parseIso(now), zoneRow?.timeZone || "UTC");

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, cutoff),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )

