input.new_string:
  it("rejects a digest hour outside 0-23", () => {
    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
  });

  it("measures the digest window on the workspace clock, across DST", () => {
    const tokyo = digestWindow(8, REFERENCE, "Asia/Tokyo");
    expect(tokyo.end).toBe("2026-03-14T23:00:00.000Z");
    expect(tokyo.start).toBe("2026-03-13T23:00:00.000Z");

    // 2026-03-08 08:00 EDT is 12:00Z; the previous local 08:00 was still EST.
    const spring = new Date("2026-03-08T12:00:00.000Z");
    const window = digestWindow(8, spring, "America/New_York");
    expect(window.end).toBe("2026-03-08T12:00:00.000Z");
    expect(window.start).toBe("2026-03-07T13:00:00.000Z");

    const fall = new Date("2026-11-01T13:00:00.000Z");
    const folded = digestWindow(8, fall, "America/New_York");
    expect(folded.end).toBe("2026-11-01T13:00:00.000Z");
    expect(folded.start).toBe("2026-10-31T12:00:00.000Z");
  });
});

